import{describe,it,expect,beforeEach,vi}from"vitest";import{TranslationClient}from"../../js-modules/i18n-translation-client.js";function fakeFetch(e,t=!0){return vi.fn().mockResolvedValue({ok:t,status:t?200:500,json:async()=>e})}describe("TranslationClient",()=>{beforeEach(()=>{localStorage.clear()}),it("skips the network call when source and target languages match",async()=>{const e=fakeFetch({translatedText:"unused"}),t=new TranslationClient({fetchImpl:e}),a=await t.translate("Hello","en",{sourceLang:"en"});expect(a).toEqual({text:"Hello",source:"skip",targetLang:"en"}),expect(e).not.toHaveBeenCalled()}),it("calls the translate endpoint and returns the AI result",async()=>{const e=fakeFetch({translatedText:"नमस्ते"}),t=new TranslationClient({fetchImpl:e}),a=await t.translate("Hello","hi");expect(a).toEqual({text:"नमस्ते",source:"ai",targetLang:"hi"}),expect(e).toHaveBeenCalledWith("/frontend/api/translate",expect.objectContaining({method:"POST"}))}),it("caches results so a repeated translation does not hit the network again",async()=>{const e=fakeFetch({translatedText:"नमस्ते"}),t=new TranslationClient({fetchImpl:e});await t.translate("Hello","hi");const a=await t.translate("Hello","hi");expect(a.source).toBe("cache"),expect(e).toHaveBeenCalledTimes(1)}),it("falls back to the original text if the provider request fails",async()=>{const e=fakeFetch({},!1),t=new TranslationClient({fetchImpl:e}),a=await t.translate("Hello","hi");expect(a).toEqual({text:"Hello",source:"error",targetLang:"hi"})}),it("de-duplicates concurrent requests for the same text and language",async()=>{const e=fakeFetch({translatedText:"नमस्ते"}),t=new TranslationClient({fetchImpl:e}),[a,n]=await Promise.all([t.translate("Hello","hi"),t.translate("Hello","hi")]);expect(a.text).toBe("नमस्ते"),expect(n.text).toBe("नमस्ते"),expect(e).toHaveBeenCalledTimes(1)})});